<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#f9eeeb">
<meta name="description" content="A little birthday celebration, made with love for Afsara.">
<title>Happy Birthday, Afsara ♡</title>
<!-- CDN dependencies: no installation, build step, or local assets. -->
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=DM+Sans:wght@400;500;600&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">
<link href="https://cdnjs.cloudflare.com/ajax/libs/animate.css/4.1.1/animate.min.css" rel="stylesheet">
<style>
/* CUSTOMIZE COLORS: change these theme variables. */
:root{--paper:#fffaf5;--pearl:#f9eeeb;--rose:#e7b3ad;--ink:#562b36;--muted:#825e66;--wine:#793443;--gold:#b47e59;--lavender:#e6dcf2;--line:rgba(121,52,67,.17);--serif:'Cormorant Garamond',Georgia,serif;--sans:'DM Sans',Arial,sans-serif}
/* Base and accessible controls */
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:32px}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.7;overflow-x:hidden}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit}a{color:inherit;text-decoration:none}button,a{touch-action:manipulation}button:focus-visible,a:focus-visible{outline:3px solid var(--wine);outline-offset:6px}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:var(--serif);font-weight:500}h2{font-size:clamp(38px,4.6vw,64px);line-height:1.05;letter-spacing:-1.3px}h2 em{font-weight:400}p{color:var(--muted)}.container{width:min(1120px,calc(100% - 64px));max-width:1120px;margin:auto}.section{padding:110px 0;position:relative}.section-heading{text-align:center;margin-bottom:52px}.label{font-size:10px;letter-spacing:3px;text-transform:uppercase;font-weight:600;color:var(--wine);margin-bottom:18px}.section-heading p{margin-top:16px}.btn-love{display:inline-flex;justify-content:center;align-items:center;gap:25px;border:1px solid var(--wine);border-radius:100px;padding:16px 30px;background:var(--wine);color:white;line-height:1.3;font-size:13px;min-height:50px;box-shadow:0 8px 25px #79344317;transition:transform .25s,background .25s,box-shadow .25s;cursor:pointer}.btn-love:hover{background:#5e2433;color:white;transform:translateY(-3px);box-shadow:0 12px 30px #79344330}.btn-love.secondary{background:transparent;color:var(--wine);box-shadow:none}.btn-love.secondary:hover{background:#fff6}.text-link{background:none;border:0;color:var(--wine);border-bottom:1px solid var(--line);padding:10px 2px;cursor:pointer;font-size:12px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.skip{position:absolute;left:16px;top:-80px;z-index:100;background:white;padding:12px}.skip:focus{top:10px}.divider{display:flex;gap:14px;align-items:center;justify-content:center;color:var(--gold);margin:24px auto}.divider:before,.divider:after{content:'';height:1px;width:52px;background:var(--line)}
/* Persistent sound control */
.music{position:fixed;right:20px;bottom:20px;z-index:40!important;background:var(--paper)!important;box-shadow:0 4px 20px #562b3620}.site-header{z-index:40!important}
/* Header and full-screen birthday scene */
.hero{min-height:850px;min-height:max(780px,100svh);position:relative;isolation:isolate;display:flex;flex-direction:column;background:radial-gradient(ellipse at 50% 43%,#fff9ee 8%,#fae9e440 50%,transparent 75%),linear-gradient(125deg,#ede5f1,#fce9e1 47%,#f5dfdf);overflow:hidden}.hero:before{content:'';position:absolute;inset:0;z-index:-1;background:radial-gradient(circle at 10% 30%,#fff8 0,transparent 28%),radial-gradient(circle at 95% 60%,#fff8 0,transparent 23%)}.site-header{width:calc(100% - 96px);max-width:1440px;margin:0 auto;min-height:92px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:3;gap:20px}.brand{font-family:var(--serif);font-style:italic;font-size:23px;white-space:nowrap}.brand span{font-style:normal;font-size:20px;margin-left:10px;color:var(--gold)}nav{display:flex;gap:32px;align-items:center;font-size:12px}nav a{padding:12px 0}nav a:hover{color:var(--gold)}.music{border:1px solid var(--line);border-radius:50px;background:#fff5;padding:8px 14px;display:flex;gap:7px;align-items:center;font-size:11px;min-height:40px;cursor:pointer;color:var(--ink)}.music[hidden]{display:none}.hero-content{position:relative;text-align:center;padding:68px 20px 58px;flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:1}.birthday-heading{font-family:var(--serif);font-size:clamp(33px,3.8vw,54px);font-style:italic;letter-spacing:-.5px;position:relative;z-index:2}.balloon-stage{position:relative;width:min(1050px,100%);height:clamp(200px,28vw,350px);margin:-3px auto -5px;cursor:grab;touch-action:pan-y}.balloon-stage:active{cursor:grabbing}.balloon-stage canvas{display:block;position:absolute;inset:0;width:100%;height:100%;opacity:0;transition:opacity .8s}.balloon-stage.ready canvas{opacity:1}.balloon-stage.ready .name-fallback{opacity:0}.name-fallback{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-family:Arial,sans-serif;font-weight:900;font-size:clamp(62px,15vw,176px);letter-spacing:.02em;color:#b56a60;text-shadow:0 2px #fff7,2px 5px 0 #914f4b,0 12px 25px #8b4e5830;transition:opacity .8s}.hero-subtitle{font-family:var(--serif);font-size:clamp(23px,2.3vw,31px);font-style:italic;line-height:1.3;color:var(--ink);max-width:430px;margin-bottom:28px}.hero-content .divider{margin:3px auto 23px}.hero-hint{font-size:10px;letter-spacing:1px;margin-top:18px;color:#805b62}.scroll-note{font-size:9px;letter-spacing:2px;text-transform:uppercase;display:flex;gap:16px;align-items:center;margin-top:48px;color:var(--muted)}.scroll-note:before,.scroll-note:after{content:'';width:35px;height:1px;background:var(--line)}.star{position:absolute;color:var(--gold);font-family:Georgia,serif;pointer-events:none;animation:twinkle 5s ease-in-out infinite;z-index:0}.s1{top:24%;left:10%;font-size:36px}.s2{top:38%;right:9%;font-size:54px;animation-delay:-2s}.s3{bottom:23%;left:18%;font-size:23px;animation-delay:-1s}.s4{top:17%;right:23%;font-size:16px}.s5{bottom:13%;right:20%;font-size:20px;animation-delay:-3s}.orb{position:absolute;pointer-events:none;border-radius:50%;background:radial-gradient(circle at 30% 25%,#fffef9 0%,#fff8 8%,#f2c6c733 30%,#de919c55 65%,#fff8 73%,#c77e9622 83%);box-shadow:inset 1px 2px 8px #fff9,inset -4px -6px 15px #b8839320,0 18px 38px #bc809417;border:1px solid #ffffff80;animation:float 8s ease-in-out infinite}.orb.one{width:160px;height:190px;left:-60px;top:42%;transform:rotate(-15deg)}.orb.two{width:105px;height:125px;right:35px;top:17%;animation-delay:-3s}.orb.three{width:78px;height:91px;right:-25px;bottom:15%;animation-delay:-5s}.orb:after{content:'';position:absolute;top:100%;left:50%;width:30px;height:150px;border-left:1px solid #b7878b60;border-radius:50%;transform:rotate(12deg)}.hero-bottom{height:35px;background:linear-gradient(transparent,var(--paper));position:absolute;bottom:0;left:0;right:0}
/* Letter and folded envelope */
.letter-layout{display:grid;grid-template-columns:1.05fr .95fr;gap:90px;align-items:center}.letter-copy h2{margin-bottom:26px}.letter-copy p{margin-bottom:19px;max-width:530px;font-size:15px;line-height:1.95}.signature{font-family:var(--serif);font-style:italic;font-size:31px;color:var(--wine);margin-top:28px}.envelope-scene{height:410px;position:relative;display:flex;align-items:center;justify-content:center}.envelope-scene:before{content:'';width:min(360px,100%);height:360px;position:absolute;border-radius:50%;background:radial-gradient(#edceca77,transparent 70%)}.envelope{position:relative;width:330px;height:225px;background:#e3aaa6;transform:rotate(-8deg);box-shadow:0 30px 50px #754d4520;border:1px solid #d9a39e;border-radius:3px}.note{position:absolute;bottom:70px;left:22px;right:22px;height:225px;background:#fffaf2;border:1px solid #ecdcd0;padding:30px 20px;text-align:center;transform:rotate(6deg);box-shadow:0 3px 20px #5a2c3312;transition:transform .7s,bottom .7s}.note p{font-family:var(--serif);font-size:28px;line-height:1.2;color:var(--wine)}.note .little-heart{font-size:28px;color:var(--gold);margin-bottom:12px}.envelope-scene:hover .note{bottom:92px;transform:rotate(2deg)}.fold-left,.fold-right{position:absolute;inset:0;clip-path:polygon(0 0,55% 53%,0 100%);background:linear-gradient(135deg,#f6d6c9,#e8bbb5);z-index:1}.fold-right{clip-path:polygon(100% 0,45% 53%,100% 100%);background:linear-gradient(225deg,#f3d1c6,#dfaaa7)}.fold-bottom{position:absolute;inset:0;background:linear-gradient(#efc9bd,#edc5bd);clip-path:polygon(0 100%,0 97%,50% 42%,100% 97%,100% 100%);z-index:2}.seal{position:absolute;left:calc(50% - 28px);top:100px;width:56px;height:56px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#eec7a3,#bd7d5c);border:5px double #ce9971;box-shadow:0 4px 7px #87523c40,inset 0 1px 3px #ffe7cf;color:#865136;font-size:30px;z-index:3;display:grid;place-items:center}.envelope-caption{position:absolute;bottom:5px;font-size:11px;letter-spacing:1px;font-style:italic}.tiny-star{position:absolute;font-size:32px;color:var(--gold);top:10px;right:25px}
/* Four little reasons */
.reasons-section{background:linear-gradient(180deg,var(--paper),#fbf0eb 50%,var(--paper));padding-top:30px}.reason-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.reason{border:1px solid #e9c7c2;border-radius:85px 85px 16px 16px;padding:42px 23px 30px;text-align:center;background:linear-gradient(160deg,#fff8,#f5dfe144);transition:transform .35s,box-shadow .35s;min-height:270px}.reason:nth-child(2){background:linear-gradient(160deg,#fff9,#f8e6d688);border-color:#e9d0b8}.reason:nth-child(3){background:linear-gradient(160deg,#fff9,#f8dfe688)}.reason:nth-child(4){background:linear-gradient(160deg,#fff9,#e9e1f388);border-color:#d9cce1}.reason:hover{transform:translateY(-9px);box-shadow:0 18px 32px #6635410b}.reason-icon{font-size:37px;color:#b47a81;height:65px;font-family:Georgia,serif;line-height:1}.reason h3{font-size:25px;font-style:italic;margin-bottom:12px}.reason p{font-size:12px;line-height:1.9}.section-heading .label{margin-bottom:16px}
/* Photo placeholders: all artwork is CSS; replace via CONFIG.photos. */
.memories{padding-top:25px}.polaroids{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;padding:14px 25px 25px}.polaroid{margin:0;background:#fffdfa;padding:13px 13px 22px;box-shadow:0 10px 35px #60434716,0 2px 4px #6043470b;transform:rotate(-5deg);transition:transform .45s;position:relative}.polaroid:nth-child(2){transform:rotate(3deg);margin-top:27px}.polaroid:nth-child(3){transform:rotate(-3deg)}.polaroid:hover{transform:rotate(0) translateY(-9px)}.polaroid:before{content:'';position:absolute;left:calc(50% - 29px);top:-12px;width:58px;height:26px;background:#d7b99b60;transform:rotate(-5deg);z-index:2;clip-path:polygon(3% 0,100% 5%,96% 100%,0 92%)}.photo-art{aspect-ratio:1/1.08;overflow:hidden;position:relative;isolation:isolate;background:#ded0e8}.photo-art img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0;z-index:2}.photo-art img[hidden]{display:none}.photo-art.night{background:linear-gradient(#b6a3ce,#efd0d1)}.moon{position:absolute;top:18%;left:60%;width:44px;height:44px;border-radius:50%;box-shadow:-11px 5px 0 0 #fff1c4;transform:rotate(-22deg)}.hill{position:absolute;width:130%;height:55%;border-radius:50% 50% 0 0;bottom:-28%;left:-35%;background:#9382ae}.hill.back{left:20%;bottom:-20%;background:#aa98bf}.night:after{content:'✧  ·   ✦     ·';position:absolute;top:18%;left:15%;font-size:24px;letter-spacing:7px;color:#fff5db}.photo-art.flowers{background:linear-gradient(120deg,#e9d6c2,#fff2dc 48%,#e5c7bf)}.flowers:before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(125deg,transparent 0 45px,#fff7 46px 67px,transparent 68px 100px)}.vase{position:absolute;left:36%;bottom:12%;width:28%;height:33%;background:linear-gradient(90deg,#faf6eacc,#ffffffbb,#d5c1b899);border:1px solid #fff9;border-radius:8px 8px 25px 25px}.stem{position:absolute;bottom:36%;left:50%;width:2px;height:36%;background:#969c78;transform:rotate(-20deg);transform-origin:bottom}.stem:nth-child(2){transform:rotate(22deg);height:43%}.stem:nth-child(3){transform:rotate(0deg);height:49%}.stem:before{content:'';position:absolute;left:-14px;top:-13px;width:30px;height:36px;background:linear-gradient(90deg,#b97988,#e8b5b8,#cd8d9d);border-radius:4px 4px 50% 50%;box-shadow:inset 0 0 0 1px #ae6c7d22}.stem:after{content:'';position:absolute;top:45%;left:2px;width:17px;height:35px;border-radius:100% 0;background:#9fa482;transform:rotate(20deg)}.photo-art.sunset{background:linear-gradient(#d4b5d7 0%,#f3bdb1 38%,#f4d6ad 55%,#b9a4c6 56%,#d5b7cf 80%,#eacacb)}.sun{position:absolute;top:41%;left:47%;width:43px;height:43px;background:#fff1cb;border-radius:50%;box-shadow:0 0 24px #fff2c499}.sunset:after{content:'';position:absolute;inset:56% 0 0;background:repeating-linear-gradient(174deg,transparent 0 17px,#fff3 18px 19px,transparent 20px 28px)}.polaroid figcaption{text-align:center;font-family:var(--serif);font-size:22px;font-style:italic;line-height:1.3;padding:20px 8px 0;color:var(--ink)}.polaroid figcaption small{font-family:var(--sans);font-size:9px;letter-spacing:1px;display:block;margin-top:8px;color:var(--muted)}
/* Wish scene: original cake photograph embedded in this file, with animated candle overlays. */
.wish-section{background:radial-gradient(ellipse at center,#fff8eb 0%,#f5e1db 75%);overflow:hidden;text-align:center;padding:95px 0 85px;border-top:1px solid #fff;border-bottom:1px solid #fff}.wish-section .section-heading{margin-bottom:0}.cake-button{display:block;position:relative;width:320px;height:285px;margin:8px auto 12px;background:transparent;border:0;padding:0;color:inherit;cursor:pointer;max-width:100%}.cake-button:focus-visible{outline-offset:3px;border-radius:40px}.cake-photo{position:absolute;left:0;top:-20.3125%;width:100%;height:auto;display:block;pointer-events:none;user-select:none}.cake-button{width:430px;height:auto;aspect-ratio:1266/1280;overflow:hidden;isolation:isolate;mix-blend-mode:multiply;margin:24px auto 18px}.cake-button .candle{left:calc(41.5% - 12px);bottom:64.5%}.cake-button .candle.left{left:calc(35.5% - 12px);bottom:65%}.cake-button .candle.right{left:calc(47.5% - 12px);bottom:63%}.candle{position:absolute;width:24px;height:110px;background:transparent;z-index:2}.candle.left{height:94px}.candle.right{height:100px}.candle-gold{display:block;width:100%;height:100%;overflow:visible}.wick{position:absolute;top:-4px;left:11px;width:2px;height:6px;background:#6b5128}.flame{position:absolute;bottom:calc(100% + 3px);left:6px;width:12px;height:27px;border-radius:65% 35% 50% 50%;background:radial-gradient(ellipse at 50% 75%,#fffef3 0 35%,#fff6c6 52%,#efc36b 80%);box-shadow:0 0 12px #ffe7a9,0 0 25px #f4bd6250;animation:flicker 1.4s ease-in-out infinite;transform-origin:bottom;transition:opacity .5s,scale .5s}.left .flame{animation-delay:-.5s}.right .flame{animation-delay:-.9s}.wished .flame{opacity:0;scale:.1}.wish-status{min-height:72px;max-width:470px;margin:20px auto 0;padding:0 15px;font-family:var(--serif);font-size:25px;line-height:1.35;color:var(--ink)}#relight[hidden]{display:none}.wish-spark{position:absolute;color:#b48161;font-size:27px}.wish-spark.a{left:20%;top:45%}.wish-spark.b{right:19%;top:61%;font-size:40px}
/* Closing and celebration canvas */
.closing{min-height:680px;min-height:90svh;display:flex;align-items:center;text-align:center;background:radial-gradient(ellipse at 15% 90%,#ffe7da,transparent 45%),radial-gradient(ellipse at 85% 70%,#efd6e3,transparent 50%),linear-gradient(#e3d9ee,#f5e0df);position:relative;overflow:hidden;padding:100px 20px}.closing h2{font-size:clamp(49px,7vw,92px);line-height:1.03;font-style:italic}.closing h2 span{font-style:normal;letter-spacing:8px;display:block;margin-top:8px}.closing p{margin:25px auto 30px;max-width:390px;font-family:var(--serif);font-size:26px;line-height:1.4}.closing .container{position:relative;z-index:1}.closing .label{font-family:var(--sans);font-size:10px;letter-spacing:3px;margin-bottom:28px}.footer-note{position:absolute;bottom:30px;left:15px;right:15px;font-size:10px;letter-spacing:1.5px;color:var(--muted)}.closing-heart{position:absolute;font-family:var(--serif);font-size:240px;line-height:1;color:#fff5;left:-50px;top:15%;transform:rotate(-20deg)}.closing-heart.right{left:auto;right:-40px;top:45%;font-size:320px;transform:rotate(20deg)}#confetti{position:fixed;inset:0;width:100%;height:100%;z-index:20;pointer-events:none}.audio-status{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);max-width:90%;background:var(--paper);padding:12px 22px;border:1px solid var(--line);border-radius:12px;box-shadow:0 4px 20px #55232c15;z-index:30;font-size:12px}.audio-status:empty{display:none}.wow{visibility:visible}body.paused *{animation-play-state:paused!important}
@keyframes float{0%,100%{translate:0 0}50%{translate:0 -17px}}@keyframes twinkle{0%,100%{opacity:.45;transform:scale(.9)}50%{opacity:.9;transform:scale(1.06)}}@keyframes flicker{0%,100%{transform:rotate(-4deg) scaleY(1)}50%{transform:rotate(5deg) scaleY(.92)}}
/* Responsive composition: 320px and up. */
@media(min-width:1600px){.hero-content{padding-top:95px;padding-bottom:95px}.balloon-stage{width:1150px;height:370px}}
@media(max-width:1023px){.site-header{width:calc(100% - 48px)}nav{gap:20px}.letter-layout{gap:35px}.envelope{width:285px;height:205px}.reason-grid{grid-template-columns:repeat(2,1fr);gap:20px}.reason{min-height:235px;padding:30px}.polaroids{gap:23px;padding-left:10px;padding-right:10px}.polaroid figcaption{font-size:20px}.section{padding:80px 0}.reasons-section,.memories{padding-top:25px}.hero{min-height:max(720px,100svh)}}
@media(max-width:767px){.cake-button .candle{height:88px}.cake-button .candle.left{height:74px}.cake-button .candle.right{height:80px}.container{width:calc(100% - 40px)}.site-header{min-height:75px;width:calc(100% - 40px)}.brand{font-size:21px}nav a{display:none}nav{gap:0}.hero{min-height:max(680px,100svh)}.hero-content{padding:60px 12px 55px}.birthday-heading{font-size:38px}.balloon-stage{height:clamp(165px,44vw,270px);margin:12px auto 8px;width:100%}.name-fallback{font-size:16vw}.hero-subtitle{max-width:300px;font-size:25px}.hero-hint{max-width:260px}.scroll-note{margin-top:40px;font-size:8px}.s1{left:5%;top:26%;font-size:24px}.s2{right:5%;top:51%;font-size:26px}.s3{left:7%;bottom:22%}.orb.one{width:85px;height:110px;left:-47px;top:58%}.orb.two{width:60px;height:76px;right:-15px;top:18%}.orb.three{display:none}.letter-layout{grid-template-columns:1fr;gap:20px}.letter-copy{max-width:520px;margin:auto}.envelope-scene{height:335px;max-width:360px;width:100%;margin:25px auto 0}.envelope{width:275px;height:200px}.note{height:200px;bottom:60px}.note p{font-size:26px}.envelope-caption{bottom:0}.reason-grid{gap:13px}.reason{border-radius:60px 60px 12px 12px;padding:30px 16px 24px;min-height:255px}.reason h3{font-size:24px}.reason p{font-size:12px;line-height:1.7}.reason-icon{height:54px;font-size:31px}.section-heading{margin-bottom:36px}h2{letter-spacing:-.8px}.polaroids{grid-template-columns:1fr;gap:40px;max-width:330px;margin:0 auto;padding:10px 15px 20px}.polaroid:nth-child(2){margin-top:0}.polaroid figcaption{font-size:23px}.wish-section{padding:75px 0 60px}.wish-spark.a{left:5%;top:38%}.wish-spark.b{right:5%;top:60%;font-size:23px}.closing{min-height:640px}.closing h2 span{letter-spacing:4px}.closing .label{font-size:8px;letter-spacing:2px}.closing p{font-size:24px}.section{padding:70px 0}.reasons-section,.memories{padding-top:15px}}
@media(max-width:359px){.container{width:calc(100% - 32px)}.brand{font-size:18px}.brand span{margin-left:3px}.reason-grid{grid-template-columns:1fr}.reason{min-height:auto;border-radius:65px 65px 15px 15px;padding:30px}.balloon-stage{height:165px}.hero-subtitle{font-size:23px}.cake-button{width:100%;margin:24px auto 18px}.cake-button .candle{height:70px}.cake-button .candle.left{height:62px}.cake-button .candle.right{height:66px}.envelope{width:250px}.music{padding:8px 10px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}.wow{visibility:visible!important}.polaroid:hover,.reason:hover,.btn-love:hover{transform:none}}
</style>
</head>
<body>
<a class="skip" href="#letter">Skip to your birthday letter</a>
<main>
<section class="hero" id="home" aria-labelledby="birthday-title">
<header class="site-header"><a class="brand" href="#home">A little celebration <span aria-hidden="true">✧</span></a><nav aria-label="Birthday page"><a href="#letter">The letter</a><a href="#little-things">Little things</a><a href="#wish">Make a wish</a><button class="music" id="music-toggle" aria-pressed="false" title="Play birthday piano and celebration sounds"><span aria-hidden="true">♫</span><span id="music-label">Play music</span></button></nav></header>
