<canvas id="confetti" aria-hidden="true"></canvas><audio id="birthday-audio" loop preload="auto" src="data:audio/mpeg;base64,"></audio><audio id="cheer-audio" preload="auto" src="data:audio/mpeg;base64,"></audio><div class="audio-status" id="audio-status" role="status"></div>
<noscript><p style="padding:20px;text-align:center">Happy Birthday, Afsara. Enable JavaScript for the floating balloons and candle wish.</p></noscript>
<!-- Version-pinned CDN scripts. Core interactions initialize before optional libraries load. -->
<script>
'use strict';
/* ================= CUSTOMIZATION =================
   1. MESSAGE: set message to an array of paragraphs, or edit #birthday-message above.
   2. PHOTOS: supply HTTPS image URLs (or data:image URLs to keep personal photos embedded).
      Leave url empty to retain the finished pastel illustrations. No local files needed.
   3. AUDIO: a synthesized birthday piano loop and recorded crowd cheers are embedded.
      Set audioUrl to an HTTPS MP3 URL to replace the piano. First interaction starts audio.
   4. COLORS: edit :root near the beginning of <style>.
   5. OTHER TEXT: edit the HTML headings/reason cards, or the settings below.
   CDN access requires internet. Embedded photo and audio work offline.
   Audio credit: Crowd Cheering by SoundsExciting, CC0, trimmed with fade-out.
   https://freesound.org/people/SoundsExciting/sounds/365132/
   https://creativecommons.org/publicdomain/zero/1.0/
   Piano: original synthesized arrangement of the traditional birthday melody.
=================================================== */
const CONFIG = {
  message: [],
  signature: 'With all my love ♡',
  wishMessage: 'May everything your heart is quietly hoping for find its way to you. Happy Birthday, Afsara. ♡',
  closingMessage: 'Of all the things to celebrate, you will always be my favorite.',
  audioUrl: '',
  photos: [
    {url:'', alt:'Our favorite memory under the stars', caption:'', subtitle:''},
    {url:'', alt:'A beautiful ordinary day together', caption:'', subtitle:''},
    {url:'', alt:'An adventure together', caption:'', subtitle:''}
  ]
};
const reduceQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
let reducedMotion = reduceQuery.matches;
function applyPersonalization(){
  if(CONFIG.message.length){const box=document.getElementById('birthday-message');box.replaceChildren();CONFIG.message.forEach(text=>{const p=document.createElement('p');p.textContent=text;box.appendChild(p);});}
  document.getElementById('signature').textContent=CONFIG.signature;
  document.getElementById('closing-message').textContent=CONFIG.closingMessage;
  CONFIG.photos.slice(0,3).forEach((photo,i)=>{
    const img=document.getElementById('photo-'+(i+1));
    if(photo.url){img.alt=photo.alt;img.onload=()=>{img.hidden=false;img.parentElement.removeAttribute('role');img.parentElement.removeAttribute('aria-label');};img.onerror=()=>{img.hidden=true;};img.src=photo.url;}
    if(photo.caption){const caption=document.getElementById('caption-'+(i+1));caption.textContent=photo.caption;if(photo.subtitle){const small=document.createElement('small');small.textContent=photo.subtitle;caption.appendChild(small);}}
  });
}
/* Small, bounded 2D confetti burst; only renders during a celebration. */
const celebration=(()=>{
  const canvas=document.getElementById('confetti'),ctx=canvas.getContext('2d');
  let bits=[],frame=0,last=0,width=0,height=0;
  const colors=['#b67879','#d9ad72','#c0a4d2','#e6bcb6','#faf1d3','#91babe'];
  function resize(){width=innerWidth;height=innerHeight;const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=width*dpr;canvas.height=height*dpr;if(ctx)ctx.setTransform(dpr,0,0,dpr,0,0);}
