  function draw(now){const dt=Math.min((now-last)/16.67,2);last=now;ctx.clearRect(0,0,width,height);bits=bits.filter(b=>b.life>0&&b.y<height+30);for(const b of bits){b.x+=b.vx*dt;b.y+=b.vy*dt;b.vy+=.055*dt;b.r+=b.spin*dt;b.life-=dt;ctx.save();ctx.globalAlpha=Math.min(1,b.life/35);ctx.translate(b.x,b.y);ctx.rotate(b.r);ctx.fillStyle=b.color;ctx.fillRect(-b.size/2,-b.size/4,b.size,b.size/2);ctx.restore();}if(bits.length)frame=requestAnimationFrame(draw);else stop();}
  function burst(){if(!ctx||reducedMotion)return;stop();resize();const n=width<768?65:115;for(let i=0;i<n;i++)bits.push({x:Math.random()*width,y:-20-Math.random()*height*.4,vx:(Math.random()-.5)*2.5,vy:2+Math.random()*2.5,r:Math.random()*6,spin:(Math.random()-.5)*.1,size:5+Math.random()*7,life:240+Math.random()*70,color:colors[i%colors.length]});last=performance.now();frame=requestAnimationFrame(draw);}
  addEventListener('resize',resize,{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});resize();return{burst,stop};
})();
/* Candle controls work without Three.js, WOW.js, Bootstrap JS, or audio. */
let wished=false;
function makeWish(){if(wished)return;wished=true;document.getElementById('cake-button').classList.add('wished');document.getElementById('cake-button').setAttribute('aria-label','Birthday candles blown out');document.getElementById('cake-button').setAttribute('aria-disabled','true');const button=document.getElementById('wish-button');button.textContent='Your wish is on its way ♡';button.setAttribute('aria-disabled','true');document.getElementById('wish-status').textContent=CONFIG.wishMessage;document.getElementById('relight').hidden=false;celebration.burst();birthdaySound.celebrate();}
function relight(){wished=false;const cake=document.getElementById('cake-button');cake.classList.remove('wished');cake.setAttribute('aria-label','Blow out the birthday candles');cake.removeAttribute('aria-disabled');const button=document.getElementById('wish-button');button.textContent='Make a wish ✧';button.removeAttribute('aria-disabled');document.getElementById('wish-status').textContent='One more wish? There is always room for a little more magic.';document.getElementById('relight').hidden=true;button.focus({preventScroll:true});}
document.getElementById('wish-button').addEventListener('click',makeWish);document.getElementById('cake-button').addEventListener('click',makeWish);document.getElementById('relight').addEventListener('click',relight);
document.getElementById('replay').addEventListener('click',()=>{celebration.burst();if(reducedMotion){document.getElementById('closing-message').textContent='One more birthday wish, and all my love, just for you. ♡';}});
/* Start within a user gesture, retain the user's mute choice, and duck (not stop)
   the looping piano during the crowd celebration. No audio network requests. */
const birthdaySound=(()=>{
  const piano=document.getElementById('birthday-audio'),cheer=document.getElementById('cheer-audio');
  const button=document.getElementById('music-toggle'),label=document.getElementById('music-label');
  const status=document.getElementById('audio-status');
  let enabled=false,explicitlyMuted=false,celebrating=false,resumeVisible=false,noticeTimer;
  const normalVolume=.36,duckVolume=.09;
  piano.volume=normalVolume;cheer.volume=.85;
  if(CONFIG.audioUrl)piano.src=CONFIG.audioUrl;
  function sync(){button.setAttribute('aria-pressed',String(enabled));label.textContent=enabled?'Mute sound':(explicitlyMuted?'Play sound':'Play music');button.title=enabled?'Mute birthday music and celebration sounds':'Play birthday music and celebration sounds';}
  function failure(){enabled=false;sync();status.textContent='Tap Play music to enable the birthday soundtrack.';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>status.textContent='',5000);}
  function start(){
    if(explicitlyMuted)return;
    enabled=true;sync();
    const promise=piano.play();
    if(promise)promise.catch(()=>{if(!explicitlyMuted)failure();});
  }
  function mute(){explicitlyMuted=true;enabled=false;piano.pause();cheer.pause();cheer.currentTime=0;celebrating=false;piano.volume=normalVolume;sync();}
  function celebrate(){
    if(explicitlyMuted)return;
    start();celebrating=true;piano.volume=duckVolume;cheer.currentTime=0;
    const promise=cheer.play();if(promise)promise.catch(()=>{celebrating=false;piano.volume=normalVolume;});
  }
  cheer.addEventListener('ended',()=>{celebrating=false;piano.volume=normalVolume;});
  button.addEventListener('click',()=>{if(enabled)mute();else{explicitlyMuted=false;start();}});
  function firstGesture(e){if(e.target.closest&&e.target.closest('#music-toggle'))return;if(!enabled&&!explicitlyMuted)start();}
  document.addEventListener('pointerdown',firstGesture,{passive:true});
  document.addEventListener('keydown',e=>{if(['Enter',' ','Tab'].includes(e.key))firstGesture(e);});
  document.addEventListener('visibilitychange',()=>{
    if(document.hidden){resumeVisible=enabled;piano.pause();cheer.pause();}
    else if(resumeVisible&&!explicitlyMuted){resumeVisible=false;start();if(celebrating)cheer.play().catch(()=>{celebrating=false;piano.volume=normalVolume;});}
  });
  piano.addEventListener('error',failure);sync();return{celebrate};
})();
applyPersonalization();

function initializeReveals(){if(reducedMotion||!window.WOW)return;try{new WOW({boxClass:'wow',animateClass:'animate__animated',offset:45,mobile:true,live:false}).init();}catch(e){document.querySelectorAll('.wow').forEach(el=>el.style.visibility='visible');}}
/* Three.js: custom vector letter outlines, beveled foil geometry, studio reflections.
