  try{
    const T=window.THREE;renderer=new T.WebGLRenderer({alpha:true,antialias:innerWidth>=768,powerPreference:'low-power'});
    renderer.setPixelRatio(Math.min(devicePixelRatio||1,innerWidth<768?1.35:1.75));renderer.outputEncoding=T.sRGBEncoding;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.9;renderer.setClearColor(0,0);host.appendChild(renderer.domElement);
    const scene=new T.Scene(),camera=new T.PerspectiveCamera(32,1,.1,100);camera.position.set(0,.05,13);
    scene.add(new T.HemisphereLight(0xfff6e6,0xb27582,.6));
    const key=new T.DirectionalLight(0xfff3d8,1.2);key.position.set(-4,5,7);scene.add(key);const rim=new T.DirectionalLight(0xe9dcff,.8);rim.position.set(5,1,2);scene.add(rim);
    const envCanvas=document.createElement('canvas');envCanvas.width=1024;envCanvas.height=512;const ec=envCanvas.getContext('2d');const grad=ec.createLinearGradient(0,0,0,512);grad.addColorStop(0,'#fff5e3');grad.addColorStop(.28,'#fffaf4');grad.addColorStop(.46,'#c38874');grad.addColorStop(.52,'#633c40');grad.addColorStop(.66,'#d5a295');grad.addColorStop(1,'#f5e7d4');ec.fillStyle=grad;ec.fillRect(0,0,1024,512);ec.fillStyle='#fffaf2';ec.fillRect(90,35,100,360);ec.fillRect(630,75,200,250);ec.fillStyle='#784a4a';ec.fillRect(440,180,36,250);const env=new T.CanvasTexture(envCanvas);env.mapping=T.EquirectangularReflectionMapping;env.encoding=T.sRGBEncoding;const pmrem=new T.PMREMGenerator(renderer),envTarget=pmrem.fromEquirectangular(env);scene.environment=envTarget.texture;env.dispose();pmrem.dispose();
    const material=new T.MeshPhysicalMaterial({color:0xbd7155,metalness:1,roughness:.19,clearcoat:1,clearcoatRoughness:.16,envMapIntensity:1.05});
    function polygon(points){const s=new T.Shape();points.forEach((p,i)=>i?s.lineTo(p[0],p[1]):s.moveTo(p[0],p[1]));s.closePath();return s;}
    function outline(letter){
