      if(letter==='F')s=polygon([[0,0],[.34,0],[.34,.64],[.99,.64],[.99,.94],[.34,.94],[.34,1.29],[1.1,1.29],[1.1,1.6],[0,1.6]]);
      if(letter==='S'){s=new T.Shape();s.moveTo(1.2,1.36);s.bezierCurveTo(.97,1.7,.22,1.76,.04,1.3);s.bezierCurveTo(-.14,.84,.26,.69,.66,.56);s.bezierCurveTo(1.05,.44,.96,.23,.66,.23);s.bezierCurveTo(.38,.2,.2,.32,.11,.44);s.lineTo(-.04,.15);s.bezierCurveTo(.25,-.13,1.07,-.16,1.23,.29);s.bezierCurveTo(1.4,.78,.97,.93,.58,1.04);s.bezierCurveTo(.22,1.14,.29,1.38,.61,1.38);s.bezierCurveTo(.82,1.38,.96,1.3,1.06,1.2);s.closePath();}
      if(letter==='R'){s=new T.Shape();s.moveTo(0,0);s.lineTo(.34,0);s.lineTo(.34,.58);s.lineTo(.62,.58);s.lineTo(.99,0);s.lineTo(1.36,0);s.lineTo(.9,.68);s.bezierCurveTo(1.44,.87,1.43,1.59,.79,1.6);s.lineTo(0,1.6);s.closePath();const h=new T.Path();h.moveTo(.34,.88);h.lineTo(.34,1.3);h.lineTo(.74,1.3);h.bezierCurveTo(1.04,1.3,1.04,.88,.74,.88);h.closePath();s.holes.push(h);}
      return s;
    }
    const geometries={},letters=[],group=new T.Group();scene.add(group);
    const widths={A:1.44,F:1.1,S:1.32,R:1.36},word='AFSARA',gap=.42,total=[...word].reduce((n,c)=>n+widths[c]+gap,0)-gap;let x=-total/2;
    const threadMaterial=new T.LineBasicMaterial({color:0xb88b82,transparent:true,opacity:.4});
    [...word].forEach((char,i)=>{
