    });
    // Sparse points add depth without a heavy particle system.
    const positions=new Float32Array(36*3);for(let i=0;i<36;i++){positions[i*3]=(Math.random()-.5)*12;positions[i*3+1]=(Math.random()-.5)*4;positions[i*3+2]=-1-Math.random()*2;}const particlesGeometry=new T.BufferGeometry();particlesGeometry.setAttribute('position',new T.BufferAttribute(positions,3));const particles=new T.Points(particlesGeometry,new T.PointsMaterial({color:0xbd9370,size:.025,transparent:true,opacity:.6}));scene.add(particles);
    let targetX=0,targetY=0,raf=0,visible=true,active=true,last=0,time=0;
    function render(now){raf=0;if(!active||document.hidden||!visible)return;const delta=last?Math.min((now-last)/1000,.04):0;last=now;if(!reducedMotion)time+=delta;group.rotation.y+=(targetX*.1-group.rotation.y)*.045;group.rotation.x+=(-targetY*.06-group.rotation.x)*.045;letters.forEach((letter,i)=>{letter.position.y=letter.userData.y+(reducedMotion?0:Math.sin(time*.85+letter.userData.phase)*.065);letter.rotation.y=reducedMotion?0:Math.sin(time*.65+i)*.055;letter.rotation.z=(i%2?-.025:.025)+(reducedMotion?0:Math.sin(time*.7+i)*.012);});renderer.render(scene,camera);if(!reducedMotion)raf=requestAnimationFrame(render);}
    function start(){if(!raf&&active&&!document.hidden&&visible){last=0;raf=requestAnimationFrame(render);}}
    function resize(){const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;const vFov=camera.fov*Math.PI/180;camera.position.z=Math.max(5.6,(total+1.1)/(2*Math.tan(vFov/2)*camera.aspect),3.6/(2*Math.tan(vFov/2)));camera.position.y=-.12;camera.updateProjectionMatrix();start();}
    host.addEventListener('pointermove',e=>{if(reducedMotion)return;const rect=host.getBoundingClientRect();targetX=(e.clientX-rect.left)/rect.width*2-1;targetY=(e.clientY-rect.top)/rect.height*2-1;});host.addEventListener('pointerleave',()=>{targetX=targetY=0;});
    document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('paused',document.hidden);if(document.hidden){cancelAnimationFrame(raf);raf=0;}else start();});
    if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)start();else{cancelAnimationFrame(raf);raf=0;}},{rootMargin:'80px'}).observe(host);
    if('ResizeObserver'in window)new ResizeObserver(resize).observe(host);else addEventListener('resize',resize,{passive:true});
    const motionChange=()=>{reducedMotion=reduceQuery.matches;targetX=targetY=0;if(reducedMotion){celebration.stop();document.querySelectorAll('.wow').forEach(el=>el.style.visibility='visible');}start();};if(reduceQuery.addEventListener)reduceQuery.addEventListener('change',motionChange);else reduceQuery.addListener(motionChange);
    renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();active=false;cancelAnimationFrame(raf);raf=0;host.classList.remove('ready');document.getElementById('hero-hint').textContent='A little celebration, made just for you.';});
    resize();renderer.render(scene,camera);host.classList.add('ready');document.getElementById('hero-hint').textContent=reducedMotion?'A little celebration, made just for you.':'Move across the letters. A little magic follows.';
  }catch(e){if(renderer)renderer.dispose();host.classList.remove('ready');}
}
</script>
